function switchRole(next){if(busy)return;$('#detail-modal').close();selected=null;role=next;filter='all';lastStatus='';syncUrl();render();loadData();}
function showStatus(text){lastStatus=text;if($('#action-status'))$('#action-status').textContent=text;}
function showError(text){if($('#core-error'))$('#core-error').textContent=text;if($('#detail-modal').open&&$('#detail-error'))$('#detail-error').textContent=text;}
async function act(fn){if(busy)return;busy=true;++sequence;loading=false;const focusAction=document.activeElement?.dataset?.action;$('#app').inert=true;$('#detail-modal').inert=true;if($('#core-error'))$('#core-error').textContent='';if($('#detail-error'))$('#detail-error').textContent='';try{await fn();}catch(e){showError(e.message);}finally{busy=false;$('#app').inert=false;$('#detail-modal').inert=false;if(focusAction&&$('#detail-modal').open)($('#detail-modal').querySelector('[data-action="'+focusAction+'"]')||$('#close-detail'))?.focus();}}
async function loadData(background=false){
 if(background&&(loading||busy||document.hidden))return;
 const seq=++sequence,base=emsBase;loading=true;
 try{
  const me=await api('/api/auth/me');if(seq!==sequence)return;const changed=actor&&(actor.role!==me.actor.role||actor.facilityId!==me.actor.facilityId);actor=me.actor;if(actor.role==='admin'){location.assign('/staff.html');return;}if(changed){initialized=false;selected=null;$('#detail-modal').close();}role=actor.role;if(role==='ems')emsBase=actor.facilityId;else receiving=actor.facilityId;syncUrl();
  const data=await api('/api/requests'+(role==='ems'?'?emsBaseId='+emsBase:'')),ready=await api('/api/readiness');policy=await api('/api/policy');
  if(seq!==sequence)return;
  requests=data.requests;notices=data.notifications;facilities=ready.facilities;states=routingStates(facilities);
  if(!initialized){initialized=true;render();}else updateViews();
  $('#sync-status').textContent='Automatic updates on · Last checked '+new Date().toLocaleTimeString();
  const requested=params.get('request');if(requested&&requests.some(r=>r.id===requested)){openDetail(requested);params.delete('request');}
 }catch(e){
  if(!initialized){$('#app').innerHTML='<main class="core-wrap"><h1>Hospital Connect</h1><p role="alert">Saved requests could not load. Use your team’s established offline backup process for urgent coordination.</p><button class="primary" id="retry">Retry</button></main>';$('#retry').onclick=()=>loadData();}
  else{$('#sync-status').textContent='Updates unavailable — use Refresh to retry.';if(!background)showError(e.message);}
 }finally{if(seq===sequence)loading=false;}
}
